	"testing"
)

func TestTaskCases(t *testing.T) {
	// 直接解析：带符号、缺补零、空白、时间、反斜杠都必须失败
	for _, bad := range []string{
		"2025-+1-10", "2025-01-+1", "2025--1-10", "2025-1-10", "2025-01-1",
		" 2025-01-10", "2025-01-10 ", "2025-01-10T00:00:00", `2025-01-\31`,
		"1900-02-29", "2025- 1-10",
	} {
		if _, err := ParseDate(bad); err == nil {
			t.Errorf("ParseDate(%q) 应失败", bad)
		} else if !errors.Is(err, ErrInvalidDate) {
			t.Errorf("ParseDate(%q) 错误应可识别为 ErrInvalidDate: %v", bad, err)
		}
	}
	// 合法日期
	for _, ok := range []string{"2000-02-29", "2024-02-29", "0001-01-01", "9999-12-31"} {
		if _, err := ParseDate(ok); err != nil {
			t.Errorf("ParseDate(%q) 应成功: %v", ok, err)
		}
	}
	// JSON：Unicode 转义与普通写法等价（ 是 '2' 的转义）
	var a, b Date
	if err := json.Unmarshal([]byte(`"2025-01-10"`), &a); err != nil {
		t.Fatalf("普通写法失败: %v", err)
	}
	if err := json.Unmarshal([]byte("\"\\u0032025-01-10\""), &b); err != nil {
		t.Fatalf("Unicode 转义写法失败: %v", err)
	}
	if !a.Equal(b) || b.String() != "2025-01-10" {
		t.Fatalf("转义写法结果不一致: %s vs %s", a, b)
	}
	// 混用普通字符与转义（ 是 '0' 的转义）
	var c Date
	if err := json.Unmarshal([]byte("\"2025-\\u00301-1\\u0030\""), &c); err != nil || !c.Equal(a) {
		t.Fatalf("混用写法失败: %v %s", err, c)
	}
	// 转义出加号（ 是 '+'， 是空格）或空白仍拒绝；非字符串拒绝；非法值保留原日期
	orig := MustParseDate("2024-05-06")
	for _, badJSON := range []string{
		"\"\\u002b2025-01-10\"", "\"\\u00202025-01-10\"",
		`"2025-+1-10"`, `"2025-01-+1"`,
		`123`, `{}`, `["2025-01-10"]`, `true`, `"2025-13-01"`,
	} {
		d := orig
		if err := json.Unmarshal([]byte(badJSON), &d); err == nil {
			t.Errorf("UnmarshalJSON(%s) 应失败", badJSON)
		} else if !errors.Is(err, ErrInvalidDate) {
			t.Errorf("UnmarshalJSON(%s) 应识别为 ErrInvalidDate: %v", badJSON, err)
		}
		if !d.Equal(orig) {
			t.Errorf("UnmarshalJSON(%s) 失败后原日期被改动: %s", badJSON, d)
		}
	}
}

