// 说明缺的是哪项日期（顺序错误时给出两项日期），原文件保持原样。
// 没有修订记录的旧档案、已修订的档案、已销毁且已有清册的档案都遵守这条规则。
func TestOpenRejectsArchivesWithInvalidRetentionDates(t *testing.T) {
	corrupt := map[string]struct {
		content string
